#pragma once
// Nunito glyph atlases (8-bit coverage), generated by tools/font_build.py.
#include <stdint.h>

namespace ui {

struct Glyph {
    uint16_t cp;      // Unicode code point
    uint16_t adv16;   // advance width, 1/16 px
    int8_t x, y;      // bitmap top left, relative to the pen on the alphabetic baseline
    uint8_t w, h;
    uint32_t off;     // into the font's bits
};

struct Font {
    uint16_t weight, size;
    int8_t top, middle;  // baseline offset below y for canvas textBaseline "top" and "middle"
    const Glyph* glyphs;
    uint16_t count;
    const uint8_t* bits;
};

extern const Font kFonts[];
extern const int kFontCount;

}  // namespace ui
